import test from 'node:test';
import assert from 'node:assert/strict';
import { patchManifest, patchGradle, CLICK_ACTION } from '../scripts/patch-android.mjs';

// Shape of the manifest generated by `npx cap add android` (Capacitor 7 template)
const MANIFEST = `<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android">
    <application android:allowBackup="true" android:label="@string/app_name">
        <activity
            android:name=".MainActivity"
            android:launchMode="singleTask"
            android:exported="true">

            <intent-filter>
                <action android:name="android.intent.action.MAIN" />
                <category android:name="android.intent.category.LAUNCHER" />
            </intent-filter>

        </activity>
    </application>
</manifest>`;

test('manifest: MainActivity accepts the notification-click intent (once)', () => {
  const out = patchManifest(MANIFEST);
  const activity = out.slice(out.indexOf('<activity'), out.indexOf('</activity>'));
  assert.ok(activity.includes(`<action android:name="${CLICK_ACTION}" />`), 'filter inside MainActivity');
  assert.ok(activity.includes('android.intent.category.DEFAULT'), 'implicit intents need DEFAULT category');
  assert.ok(activity.includes('android.intent.category.LAUNCHER'), 'launcher filter kept');
  assert.equal(patchManifest(out), out, 'idempotent');
  assert.throws(() => patchManifest('<manifest/>'));
});

test('the click action matches what the plugin puts on its notifications', () => {
  assert.equal(CLICK_ACTION, '.NOTIFICATION_CLICKED');
});

test('gradle: background runner libs dir added once', () => {
  const g = "repositories {\n    flatDir{\n        dirs '../capacitor-cordova-android-plugins/src/main/libs', 'libs'\n    }\n}";
  const out = patchGradle(g);
  assert.match(out, /background-runner\/android\/src\/main\/libs/);
  assert.equal(patchGradle(out), out);
});
